; ports.asm -- appendix C: every port, read and written
; generated by genC.py
        INCLUDE "msx.inc"
        OUTPUT "ports.rom"
        ORG $4000
        CART_HEADER init

; Every port read, in two states and with two high bytes, then written, in
; nine passes. measC.py reads the tables of reads at r1done, r3done and
; r2done, and the VDP, the PSG, the PPI and the printer at each probe.
TAB     EQU RAM_START           ; the reads: r1, r3, r2, 256 bytes each

init:   di
        ld sp,$F370
        in a,(PPI_A)
        ld e,a                  ; E: the slots, put back after every OUT
        ld a,$80
        out (VDP_CTRL),a
        ld a,$81
        out (VDP_CTRL),a        ; R#1 = $80: 16 KB, the screen off
        call clear

; r1: every port read, state 1
        ld a,$00
        out (VDP_CTRL),a
        ld a,$70
        out (VDP_CTRL),a        ; write from $3000
        ld a,$5A
        out (VDP_DATA),a        ; $3000 = $5A
        ld a,5
        out (PSG_ADDR),a
        ld a,$5A
        out (PSG_WRITE),a       ; register 5 = $5A
        ld hl,TAB+$000
        ld c,0
        ld b,$00
r1loop: in a,(VDP_CTRL)         ; the latch and F cleared
        ld a,$00
        out (VDP_CTRL),a
        ld a,$30
        out (VDP_CTRL),a        ; read from $3000
        ld a,5
        out (PSG_ADDR),a        ; register 5 chosen
        ld a,$50
        out (PPI_C),a           ; port C = $50
        in a,(c)                ; the port
        ld (hl),a
        inc hl
        inc c
        jr nz,r1loop
r1done: nop                     ; measC.py reads the table

; r3: every port read, state 1, B = $FF
        ld a,$00
        out (VDP_CTRL),a
        ld a,$70
        out (VDP_CTRL),a        ; write from $3000
        ld a,$5A
        out (VDP_DATA),a        ; $3000 = $5A
        ld a,5
        out (PSG_ADDR),a
        ld a,$5A
        out (PSG_WRITE),a       ; register 5 = $5A
        ld hl,TAB+$100
        ld c,0
        ld b,$FF
r3loop: in a,(VDP_CTRL)         ; the latch and F cleared
        ld a,$00
        out (VDP_CTRL),a
        ld a,$30
        out (VDP_CTRL),a        ; read from $3000
        ld a,5
        out (PSG_ADDR),a        ; register 5 chosen
        ld a,$50
        out (PPI_C),a           ; port C = $50
        in a,(c)                ; the port
        ld (hl),a
        inc hl
        inc c
        jr nz,r3loop
r3done: nop                     ; measC.py reads the table

; r2: every port read, state 2: SPACE held, the printer plugged in
state2: nop                     ; measC.py: SPACE held, printer in
        ld a,$00
        out (VDP_CTRL),a
        ld a,$70
        out (VDP_CTRL),a        ; write from $3000
        ld a,$A5
        out (VDP_DATA),a        ; $3000 = $A5
        ld a,5
        out (PSG_ADDR),a
        ld a,$A5
        out (PSG_WRITE),a       ; register 5 = $A5
        ld hl,TAB+$200
        ld c,0
        ld b,$00
r2loop: in a,(VDP_CTRL)         ; the latch and F cleared
        ld a,$00
        out (VDP_CTRL),a
        ld a,$30
        out (VDP_CTRL),a        ; read from $3000
        ld a,5
        out (PSG_ADDR),a        ; register 5 chosen
        ld a,$58
        out (PPI_C),a           ; port C = $58
        in a,(c)                ; the port
        ld (hl),a
        inc hl
        inc c
        jr nz,r2loop
r2done: nop                     ; measC.py reads the table

; w1: every port written, for the VDP's data port
        ld bc,0                 ; port 0, B = 0
w1loop: in a,(VDP_CTRL)         ; the latch cleared
        ld a,$15
        out (VDP_CTRL),a
        ld a,$45
        out (VDP_CTRL),a        ; write from $0515
        xor a
        out (VDP_DATA),a        ; $0515 = 0
        ld a,$00
        out (VDP_CTRL),a
        ld a,$50
        out (VDP_CTRL),a        ; write from $1000
        xor a
        out (VDP_DATA),a
        out (VDP_DATA),a
        out (VDP_DATA),a        ; $1000 to $1002 = 0
        ld a,$00
        out (VDP_CTRL),a
        ld a,$50
        out (VDP_CTRL),a        ; write from $1000
        ld a,$15
        out (c),a               ; the port
        ld d,10
waitw1: dec d
        jr nz,waitw1
w1probe: ld a,e
        out (PPI_A),a           ; the slots back
        inc c
        jr nz,w1loop

; w2: every port written, for the VDP's control port
        ld bc,0                 ; port 0, B = 0
w2loop: in a,(VDP_CTRL)         ; the latch cleared
        ld a,$15
        out (VDP_CTRL),a
        ld a,$45
        out (VDP_CTRL),a        ; write from $0515
        xor a
        out (VDP_DATA),a        ; $0515 = 0
        ld a,$00
        out (VDP_CTRL),a
        ld a,$50
        out (VDP_CTRL),a        ; write from $1000
        xor a
        out (VDP_DATA),a
        out (VDP_DATA),a
        out (VDP_DATA),a        ; $1000 to $1002 = 0
        ld a,$00
        out (VDP_CTRL),a
        ld a,$50
        out (VDP_CTRL),a        ; write from $1000
        ld a,$15
        out (c),a               ; the port
        ld a,$45
        out (c),a               ; the port
        ld a,$55
        out (VDP_DATA),a        ; $55 where the address is
        ld d,10
waitw2: dec d
        jr nz,waitw2
w2probe: ld a,e
        out (PPI_A),a           ; the slots back
        inc c
        jr nz,w2loop

; w3: every port written, for the PSG's register select
        ld bc,0                 ; port 0, B = 0
w3loop: ld a,0
        out (PSG_ADDR),a
        ld a,$00
        out (PSG_WRITE),a       ; register 0 = $00
        ld a,5
        out (PSG_ADDR),a
        ld a,$00
        out (PSG_WRITE),a       ; register 5 = $00
        xor a
        out (PSG_ADDR),a        ; register 0 chosen
        ld a,$05
        out (c),a               ; the port
        ld a,$15
        out (PSG_WRITE),a       ; $15 to the register chosen
        ld d,10
waitw3: dec d
        jr nz,waitw3
w3probe: ld a,e
        out (PPI_A),a           ; the slots back
        inc c
        jr nz,w3loop

; w4: every port written, for the PSG's data port
        ld bc,0                 ; port 0, B = 0
w4loop: ld a,5
        out (PSG_ADDR),a
        ld a,$00
        out (PSG_WRITE),a       ; register 5 = $00, and chosen
        ld a,$15
        out (c),a               ; the port
        ld d,10
waitw4: dec d
        jr nz,waitw4
w4probe: ld a,e
        out (PPI_A),a           ; the slots back
        inc c
        jr nz,w4loop

; w5: every port written, for the PPI's port A
        ld bc,0                 ; port 0, B = 0
w5loop: ld a,$15
        out (c),a               ; the port
        ld d,10
waitw5: dec d
        jr nz,waitw5
w5probe: ld a,e
        out (PPI_A),a           ; the slots back
        inc c
        jr nz,w5loop

; w6: every port written, for the PPI's port C
        ld bc,0                 ; port 0, B = 0
w6loop: ld a,$F0
        out (PPI_C),a           ; port C = $F0
        ld a,$15
        out (c),a               ; the port
        ld d,10
waitw6: dec d
        jr nz,waitw6
w6probe: ld a,e
        out (PPI_A),a           ; the slots back
        inc c
        jr nz,w6loop

; w7: every port written, for the PPI's control port
        ld bc,0                 ; port 0, B = 0
w7loop: ld a,$F0
        out (PPI_C),a           ; port C = $F0
        ld a,$05
        out (c),a               ; the port
        ld d,10
waitw7: dec d
        jr nz,waitw7
w7probe: ld a,e
        out (PPI_A),a           ; the slots back
        inc c
        jr nz,w7loop

; w8: every port written, for the printer's data
        ld bc,0                 ; port 0, B = 0
w8loop: xor a
        out ($91),a             ; the printer's data = 0
        ld a,$15
        out (c),a               ; the port
        ld d,10
waitw8: dec d
        jr nz,waitw8
w8probe: ld a,e
        out (PPI_A),a           ; the slots back
        inc c
        jr nz,w8loop

; w9: every port written, for the printer's strobe
        ld bc,0                 ; port 0, B = 0
w9loop: ld a,$50
        out ($91),a             ; the printer's data
        ld a,$05
        out ($90),a             ; the strobe at 1: a byte printed if it was 0
        ld a,$04
        out (c),a               ; the port
        ld d,10
waitw9: dec d
        jr nz,waitw9
w9probe: ld a,e
        out (PPI_A),a           ; the slots back
        inc c
        jr nz,w9loop
done:   jr done

; clear: VRAM all 0, from $0000; uses A, B, C
clear:  xor a
        out (VDP_CTRL),a
        ld a,$40
        out (VDP_CTRL),a        ; write from $0000
        ld bc,$4000
clr:    xor a
        out (VDP_DATA),a
        dec bc
        ld a,b
        or c
        jr nz,clr
        ret

        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
